.github/workflows/developer-tools.yml:wi.run:
cargo build -p latent-portable-test-host --release --locked
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
python tools/build_echo_capsule.py --output-dir target/dev-echo
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
cargo build -p latent-toolchain-smoke --example generic-capsule --target wasm32-unknown-unknown --release --locked
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
wasm-tools component new target/wasm32-unknown-unknown/release/examples/generic_capsule.wasm -o target/dev-generic.wasm
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
python tools/build_portable_dev_guests.py --output target/dev-providers
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }

foreach ($language in @('rust', 'c', 'java', 'dotnet', 'go', 'typescript')) {
  python tools/run_portable_guest_tests.py --host target/release/latent-portable-test-host.exe --language $language --applications "target/dev-applications/developer-$language-applications-$env:GITHUB_SHA" --output "target/dev-portable-$language-applications.json" --require-node-parity
  if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
}
